import json
def blocks(g):
    h,w=len(g),len(g[0]); out=[]
    for r in range(h-1):
        for c in range(w-1):
            if g[r][c]==g[r][c+1]==g[r+1][c]==g[r+1][c+1]==2:
                out.append((r,c))
    return out
def transform(g):
    g=[row[:] for row in g]; bl=sorted(blocks(g),key=lambda b:(b[1],b[0]))
    for i,(r,c) in enumerate(bl):
        v=8 if i%2==0 else 2
        for dr in (0,1):
            for dc in (0,1): g[r+dr][c+dc]=v
    return g
